python3 -c '
from evaluator import evaluate
cases = [
    ("2^3^2", 512), ("-2^2", -4), ("2^-2", 0.25),
    ("2--3", 5), ("2*-3", -6), ("8/2", 4.0), ("10/4", 2.5),
    ("1+2*3", 7), ("(1+2)*3", 9),
]
for e, exp in cases:
    r = evaluate(e)
    print(f"{e:8} = {r!r:8} type={type(r).__name__:6} {\"OK\" if r==exp and type(r)==type(exp) else \"FAIL exp=\"+repr(exp)}")
# malformed -> must be ValueError
for bad in ["(1+2", "1+", "1 2", "1++", "", ")", "3@4", "1.2.3", "2^", "*3"]:
    try:
        evaluate(bad); print(f"{bad!r:8} -> NO ERROR (FAIL)")
    except ValueError:
        print(f"{bad!r:8} -> ValueError OK")
    except Exception as ex:
        print(f"{bad!r:8} -> {type(ex).__name__} (FAIL)")
'

